-- balance for id 7 starts at 100
-- T1:
BEGIN;
SELECT balance FROM accounts WHERE id = 7;      -- app reads 100
-- T2:
BEGIN;
SELECT balance FROM accounts WHERE id = 7;      -- app reads 100
-- T1:
UPDATE accounts SET balance = 70 WHERE id = 7;  -- app computed 100 - 30
COMMIT;
-- T2:
UPDATE accounts SET balance = 50 WHERE id = 7;  -- app computed 100 - 50
COMMIT;

BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM on_call
 WHERE shift_id = 9 AND active;            -- returns 2
UPDATE on_call SET active = false
 WHERE shift_id = 9 AND doctor_id = $1;
COMMIT;
